// Cloudflare Pages Function: password gate (shared password via CFP_PASSWORD env var) + GA4 injection
const LOGO = "data:image/svg+xml;base64,";
const BG = "data:image/jpeg;base64,";
const COOKIE = "hl_auth";
const MAX_AGE = 60 * 60 * 24 * 14; // 14 days

async function tokenFor(password) {
  const data = new TextEncoder().encode("hl::" + password);
  const digest = await crypto.subtle.digest("SHA-256", data);
  return Array.from(new Uint8Array(digest)).map(function (b) { return b.toString(16).padStart(2, "0"); }).join("");
}

function loginPage(wrong) {
  const err = wrong ? '<div class="err">That password wasn’t right. Please try again.</div>' : '';
  return `<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Higher Love</title><meta name="robots" content="noindex">
<link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@600&family=EB+Garamond:ital@0;1&family=Raleway:wght@600;700&display=swap" rel="stylesheet">
<style>
:root{--gold:#d8b478;--body:#cfc6ba;}
*{margin:0;padding:0;box-sizing:border-box;}
html,body{height:100%;}
body{font-family:'Raleway',sans-serif;background:#000;color:#fff;}
.wrap{min-height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:2rem 1.5rem;background:linear-gradient(rgba(0,0,0,0.55),rgba(0,0,0,0.75)),url(${BG});background-size:cover;background-position:center;}
.logo{width:210px;max-width:70vw;margin-bottom:1.8rem;}
.eyb{color:var(--gold);font-weight:700;font-size:0.66rem;letter-spacing:0.2em;text-transform:uppercase;margin-bottom:1rem;}
h1{font-family:'Cormorant Garamond',serif;font-weight:600;text-transform:uppercase;letter-spacing:0.03em;font-size:clamp(1.7rem,5vw,2.4rem);line-height:1.14;text-shadow:0 2px 14px rgba(0,0,0,0.6);}
.sub{font-family:'EB Garamond',serif;font-style:italic;color:var(--body);font-size:1.1rem;margin:0.6rem 0 1.7rem;}
form{display:flex;width:100%;max-width:360px;}
input{flex:1;background:rgba(0,0,0,0.4);border:1px solid rgba(255,255,255,0.4);border-right:none;color:#fff;font-family:'Raleway',sans-serif;font-size:0.8rem;letter-spacing:0.05em;padding:0.95rem 1rem;}
input::placeholder{color:rgba(255,255,255,0.6);}
button{font-family:'Raleway',sans-serif;font-weight:700;font-size:0.72rem;letter-spacing:0.14em;text-transform:uppercase;color:#111;background:var(--gold);border:1px solid var(--gold);padding:0.95rem 1.5rem;cursor:pointer;}
.err{color:#e6b8a2;font-family:'EB Garamond',serif;font-style:italic;font-size:0.98rem;margin-bottom:1rem;}
</style></head><body>
<div class="wrap">
  <img class="logo" src="${LOGO}" alt="Higher Love">
  <div class="eyb">By Referral &amp; Invitation</div>
  <h1>This Room Is Private</h1>
  <div class="sub">Enter the password from your invitation.</div>
  ${err}
  <form method="POST" action="/__auth" autocomplete="off">
    <input type="password" name="password" placeholder="Password" autofocus>
    <button type="submit">Enter</button>
  </form>
</div>
</body></html>`;
}

function loginResponse(wrong) {
  return new Response(loginPage(wrong), { status: 401, headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" } });
}

export async function onRequest(context) {
  const { request, env } = context;
  const url = new URL(request.url);
  const password = env.CFP_PASSWORD;

  // Gate is active only when CFP_PASSWORD is set (fail-open so the site keeps working until you set it)
  if (password) {
    const token = await tokenFor(password);

    if (request.method === "POST" && url.pathname === "/__auth") {
      let entered = "";
      try { const form = await request.formData(); entered = (form.get("password") || "").toString(); } catch (e) {}
      if (entered === password) {
        return new Response(null, { status: 302, headers: {
          "Location": "/",
          "Set-Cookie": COOKIE + "=" + token + "; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=" + MAX_AGE
        }});
      }
      return loginResponse(true);
    }

    const cookie = request.headers.get("Cookie") || "";
    const authed = cookie.split(/;\s*/).indexOf(COOKIE + "=" + token) !== -1;
    if (!authed) return loginResponse(false);
  }

  // ---- authed (or gate disabled): serve the page and inject GA4 ----
  const response = await context.next();
  const contentType = response.headers.get('content-type') || '';
  if (!contentType.includes('text/html')) return response;

  const gaScript = `
<!-- Google tag (gtag.js) -->
<script async src="https://www.googletagmanager.com/gtag/js?id=G-GJ7G3P2PEK"></script>
<script>
  window.dataLayer = window.dataLayer || [];
  function gtag(){dataLayer.push(arguments);}
  gtag('js', new Date());
  gtag('config', 'G-GJ7G3P2PEK');
</script>`;

  return new HTMLRewriter()
    .on('head', { element(element) { element.append(gaScript, { html: true }); } })
    .transform(response);
}
